/* ─── Design Tokens ─────────────────────────────────────────────────────── */
:root {
  --clr-brand:       #1a1a2e;
  --clr-brand-mid:   #16213e;
  --clr-accent:      #e94560;
  --clr-accent-dark: #c73652;
  --clr-surface:     #ffffff;
  --clr-bg:          #f7f7f9;
  --clr-bg-alt:      #eeeef3;
  --clr-text:        #1a1a2e;
  --clr-text-muted:  #5a5a72;
  --clr-border:      #d8d8e4;
  --clr-deal-bg:     #fff7ed;
  --clr-deal-border: #f59e0b;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;

  --shadow-card: 0 2px 8px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-hover: 0 8px 24px rgba(0,0,0,.12), 0 2px 6px rgba(0,0,0,.08);

  --font-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;

  --transition: 200ms ease;
  --focus-ring: 0 0 0 3px rgba(233,69,96,.4);
}

/* ─── Reset / Base ──────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; height: auto; }
ul { list-style: none; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; }

/* ─── Accessibility utilities ───────────────────────────────────────────── */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* Skip link visible on focus */
.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--clr-accent);
  color: #fff;
  padding: .75rem 1.25rem;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) 0;
  z-index: 9999;
  transform: translateY(-100%);
  transition: transform var(--transition);
}
.skip-link:focus { transform: translateY(0); outline: 3px solid #fff; outline-offset: 2px; }

/* Global focus ring */
:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--radius-sm);
}

/* ─── Layout helpers ────────────────────────────────────────────────────── */
.container { max-width: 1280px; margin-inline: auto; padding-inline: 1.5rem; }
.section { padding-block: 4rem; }
.section-header { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 2rem; flex-wrap: wrap; }
.section-title { font-size: clamp(1.4rem, 2.5vw, 1.875rem); font-weight: 700; color: var(--clr-text); }
.see-all { font-size: .875rem; font-weight: 600; color: var(--clr-accent); text-decoration: underline; white-space: nowrap; }
.see-all:hover { color: var(--clr-accent-dark); }
.see-all:focus-visible { box-shadow: var(--focus-ring); }

/* ─── Announcement bar ──────────────────────────────────────────────────── */
.announcement-bar {
  background: var(--clr-brand);
  color: #fff;
  text-align: center;
  padding: .625rem 3rem;
  font-size: .875rem;
  position: relative;
}
.announcement-bar__text strong { color: #ffd700; }

.announcement-bar__close {
  position: absolute;
  right: 1rem; top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.25rem;
  line-height: 1;
  padding: .25rem .5rem;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.announcement-bar__close:hover { background: rgba(255,255,255,.15); }
.announcement-bar__close:focus-visible { box-shadow: 0 0 0 3px rgba(255,255,255,.6); }

/* ─── Header ────────────────────────────────────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  position: sticky; top: 0;
  z-index: 100;
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding-block: 1rem;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--clr-brand);
}
.site-logo:focus-visible { box-shadow: var(--focus-ring); border-radius: var(--radius-sm); }
.site-logo__icon { width: 32px; height: 32px; }

/* Primary nav */
.primary-nav { display: flex; align-items: center; justify-content: center; }
.primary-nav__list { display: flex; gap: .25rem; }
.primary-nav__link {
  padding: .5rem .875rem;
  border-radius: var(--radius-sm);
  font-weight: 500;
  font-size: .9375rem;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.primary-nav__link:hover { color: var(--clr-text); background: var(--clr-bg); }
.primary-nav__link[aria-current="page"] {
  color: var(--clr-text);
  background: var(--clr-bg-alt);
  font-weight: 700;
}
.primary-nav__link:focus-visible { box-shadow: var(--focus-ring); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; }
.icon-btn {
  background: transparent;
  border: none;
  padding: .5rem;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  display: flex; align-items: center; justify-content: center;
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover { color: var(--clr-text); background: var(--clr-bg); }
.icon-btn:focus-visible { box-shadow: var(--focus-ring); }
.icon-btn svg { width: 22px; height: 22px; }

.cart-badge {
  position: absolute; top: 3px; right: 3px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  background: transparent;
  border: none;
  padding: .5rem;
  border-radius: var(--radius-sm);
  color: var(--clr-text);
}
.menu-toggle:focus-visible { box-shadow: var(--focus-ring); }
.menu-toggle svg { width: 24px; height: 24px; }

/* ─── Hero ──────────────────────────────────────────────────────────────── */
.hero {
  background: var(--clr-brand);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 3rem;
  min-height: 560px;
  padding-block: 4rem;
}
.hero__eyebrow {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: .75rem;
}
.hero__title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1rem;
}
.hero__title em { color: var(--clr-accent); font-style: normal; }
.hero__description {
  font-size: 1.0625rem;
  color: rgba(255,255,255,.75);
  max-width: 42ch;
  margin-bottom: 2rem;
}
.hero__actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.hero-image-wrap {
  position: relative;
  display: flex; align-items: center; justify-content: center;
}
.hero-image-wrap::before {
  content: '';
  position: absolute; inset: -2rem;
  background: radial-gradient(circle at 60% 50%, rgba(233,69,96,.25) 0%, transparent 70%);
}
.hero-image {
  width: 100%;
  max-width: 500px;
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  object-fit: cover;
}

/* ─── Buttons ───────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: .5rem;
  border: none;
  border-radius: var(--radius-sm);
  padding: .75rem 1.5rem;
  font-size: .9375rem;
  font-weight: 600;
  font-family: inherit;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition), transform var(--transition);
  white-space: nowrap;
}
@media (prefers-reduced-motion: no-preference) {
  .btn:active { transform: scale(.98); }
}
.btn:focus-visible { box-shadow: var(--focus-ring); }

.btn--primary { background: var(--clr-accent); color: #fff; }
.btn--primary:hover { background: var(--clr-accent-dark); }

.btn--outline { background: transparent; color: #fff; border: 2px solid rgba(255,255,255,.4); }
.btn--outline:hover { border-color: #fff; background: rgba(255,255,255,.1); }

.btn--ghost { background: transparent; color: var(--clr-text); border: 2px solid var(--clr-border); }
.btn--ghost:hover { border-color: var(--clr-text-muted); background: var(--clr-bg-alt); }

.btn--sm { padding: .5rem 1rem; font-size: .875rem; }

/* ─── Product grid ──────────────────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--clr-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
}
.product-card:not(:hover) { box-shadow: var(--shadow-card); }

.product-card__img-wrap { position: relative; aspect-ratio: 1; overflow: hidden; background: var(--clr-bg-alt); }
.product-card__img { width: 100%; height: 100%; object-fit: cover;
  transition: transform 300ms ease; }
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover .product-card__img { transform: scale(1.04); }
}

.product-card__badge {
  position: absolute; top: .75rem; left: .75rem;
  background: var(--clr-accent); color: #fff;
  font-size: .6875rem; font-weight: 700;
  letter-spacing: .06em; text-transform: uppercase;
  padding: .2rem .6rem;
  border-radius: var(--radius-sm);
}
.product-card__badge--new { background: var(--clr-brand-mid); }

.product-card__wishlist {
  position: absolute; top: .75rem; right: .75rem;
  background: rgba(255,255,255,.92);
  border: 1px solid var(--clr-border);
  border-radius: 50%;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  transition: background var(--transition), border-color var(--transition);
}
.product-card__wishlist:hover { background: #fff; border-color: var(--clr-accent); }
.product-card__wishlist[aria-pressed="true"] { color: var(--clr-accent); background: #fff; }
.product-card__wishlist:focus-visible { box-shadow: var(--focus-ring); }

.product-card__body { padding: 1rem; display: flex; flex-direction: column; gap: .375rem; flex: 1; }
.product-card__category { font-size: .75rem; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; color: var(--clr-text-muted); }

.product-card__name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--clr-text);
  text-decoration: none;
  display: block;
}
.product-card__name:hover { color: var(--clr-accent); }
.product-card__name:focus-visible { box-shadow: var(--focus-ring); border-radius: 2px; }

.product-card__rating { display: flex; align-items: center; gap: .375rem; margin-top: .125rem; }
.stars { color: #f59e0b; font-size: .875rem; letter-spacing: -.05em; }
.rating-count { font-size: .75rem; color: var(--clr-text-muted); }

.product-card__footer { padding: .75rem 1rem 1rem; border-top: 1px solid var(--clr-border); margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: .5rem; }
.price-wrap { display: flex; align-items: baseline; gap: .375rem; }
.price { font-size: 1.125rem; font-weight: 700; color: var(--clr-text); }
.price--sale { color: var(--clr-accent); }
.price--original { font-size: .875rem; font-weight: 400; color: var(--clr-text-muted); text-decoration: line-through; }

/* ─── Deals section ─────────────────────────────────────────────────────── */
.deals-section { background: var(--clr-deal-bg); }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--clr-surface);
  border: 2px solid var(--clr-deal-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: grid;
  grid-template-columns: 120px 1fr;
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-hover); }

.deal-card__img-wrap { overflow: hidden; background: var(--clr-bg-alt); }
.deal-card__img { width: 100%; height: 100%; object-fit: cover;
  transition: transform 300ms ease; }
@media (prefers-reduced-motion: no-preference) {
  .deal-card:hover .deal-card__img { transform: scale(1.06); }
}
.deal-card__content { padding: 1rem; display: flex; flex-direction: column; gap: .375rem; }
.deal-card__tag { font-size: .6875rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: #b45309; }
.deal-card__name { font-size: .9375rem; font-weight: 600; line-height: 1.3; }
.deal-card__name a { color: var(--clr-text); text-decoration: none; }
.deal-card__name a:hover { color: var(--clr-accent); }
.deal-card__name a:focus-visible { box-shadow: var(--focus-ring); border-radius: 2px; }
.deal-card__savings { font-size: .875rem; color: var(--clr-text-muted); margin-top: auto; }
.deal-card__savings strong { color: #b45309; }
.deal-timer { font-size: .75rem; font-weight: 600; color: #dc2626; display: flex; align-items: center; gap: .25rem; margin-top: .25rem; }

/* Countdown */
.countdown { display: flex; align-items: center; gap: .25rem; font-size: .75rem; font-weight: 700; color: #dc2626; }
.countdown__segment { background: #dc2626; color: #fff; padding: .1rem .35rem; border-radius: 3px; min-width: 1.75rem; text-align: center; }
.countdown__sep { color: #dc2626; }

/* Featured banner */
.deal-banner {
  background: linear-gradient(135deg, var(--clr-brand-mid) 0%, var(--clr-brand) 100%);
  color: #fff;
  border-radius: var(--radius-md);
  padding: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}
.deal-banner__text h3 { font-size: clamp(1.1rem, 2.5vw, 1.5rem); font-weight: 700; margin-bottom: .375rem; }
.deal-banner__text h3 span { color: #ffd700; }
.deal-banner__text p { font-size: .9375rem; color: rgba(255,255,255,.75); }

/* ─── Editorial section ─────────────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.editorial-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-hover); }
.editorial-card--featured { grid-row: span 2; }

.editorial-card__img-wrap { overflow: hidden; }
.editorial-card--featured .editorial-card__img-wrap { flex: 0 0 300px; }
.editorial-card__img { width: 100%; height: 200px; object-fit: cover;
  transition: transform 300ms ease; }
.editorial-card--featured .editorial-card__img { height: 280px; }
@media (prefers-reduced-motion: no-preference) {
  .editorial-card:hover .editorial-card__img { transform: scale(1.04); }
}

.editorial-card__body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.editorial-card__tag {
  display: inline-block;
  font-size: .6875rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;
  color: var(--clr-accent);
  margin-bottom: .5rem;
}
.editorial-card__title { font-size: 1.0625rem; font-weight: 700; line-height: 1.3; margin-bottom: .5rem; }
.editorial-card--featured .editorial-card__title { font-size: 1.3125rem; }
.editorial-card__title a { color: var(--clr-text); text-decoration: none; }
.editorial-card__title a:hover { color: var(--clr-accent); }
.editorial-card__title a:focus-visible { box-shadow: var(--focus-ring); border-radius: 2px; }
.editorial-card__excerpt { font-size: .9rem; color: var(--clr-text-muted); line-height: 1.55; margin-bottom: 1rem; }
.editorial-card__meta { display: flex; align-items: center; gap: .75rem; margin-top: auto; font-size: .8125rem; color: var(--clr-text-muted); }
.editorial-card__meta-dot { color: var(--clr-border); }

/* ─── Newsletter ────────────────────────────────────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, var(--clr-brand) 0%, var(--clr-brand-mid) 100%);
  color: #fff;
  text-align: center;
}
.newsletter-section .section-title { color: #fff; }
.newsletter-description { font-size: 1rem; color: rgba(255,255,255,.75); max-width: 50ch; margin: 0 auto 1.5rem; }
.newsletter-form { display: flex; gap: .75rem; max-width: 480px; margin-inline: auto; flex-wrap: wrap; justify-content: center; }
.newsletter-input {
  flex: 1 1 220px;
  padding: .75rem 1.1rem;
  border: 2px solid rgba(255,255,255,.3);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.1);
  color: #fff;
  font-family: inherit;
  font-size: .9375rem;
}
.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
.newsletter-input:focus { outline: none; border-color: rgba(255,255,255,.7); box-shadow: 0 0 0 3px rgba(255,255,255,.2); }
.newsletter-input:focus-visible { border-color: rgba(255,255,255,.7); box-shadow: 0 0 0 3px rgba(255,255,255,.2); }
.newsletter-status { margin-top: 1rem; font-size: .9375rem; min-height: 1.5em; }
.newsletter-status--success { color: #86efac; }
.newsletter-status--error { color: #fca5a5; }

/* ─── Categories strip ──────────────────────────────────────────────────── */
.categories-strip { background: var(--clr-surface); border-bottom: 1px solid var(--clr-border); }
.categories-list { display: flex; gap: 1rem; overflow-x: auto; padding-block: 1rem; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.categories-list::-webkit-scrollbar { display: none; }
.category-pill {
  flex: 0 0 auto;
  display: flex; flex-direction: column; align-items: center; gap: .375rem;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-lg);
  border: 2px solid var(--clr-border);
  background: var(--clr-surface);
  font-size: .8125rem; font-weight: 600;
  color: var(--clr-text-muted);
  text-align: center;
  transition: border-color var(--transition), color var(--transition), background var(--transition);
  text-decoration: none;
  min-width: 80px;
}
.category-pill:hover, .category-pill[aria-current="true"] {
  border-color: var(--clr-accent);
  color: var(--clr-accent);
  background: #fef2f4;
}
.category-pill:focus-visible { box-shadow: var(--focus-ring); }
.category-pill__icon { font-size: 1.5rem; line-height: 1; }

/* ─── Footer ────────────────────────────────────────────────────────────── */
.site-footer {
  background: var(--clr-brand);
  color: rgba(255,255,255,.8);
  padding-block: 3rem 1.5rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 2.5rem;
}
.footer-brand .site-logo { color: #fff; }
.footer-brand-description { font-size: .875rem; color: rgba(255,255,255,.6); margin-top: .75rem; max-width: 28ch; line-height: 1.6; }

.footer-col__heading { font-size: .875rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: .06em; margin-bottom: .875rem; }
.footer-nav__list { display: flex; flex-direction: column; gap: .5rem; }
.footer-nav__link { font-size: .875rem; color: rgba(255,255,255,.65); transition: color var(--transition); }
.footer-nav__link:hover { color: #fff; }
.footer-nav__link:focus-visible { box-shadow: 0 0 0 3px rgba(255,255,255,.5); border-radius: 2px; }

.footer-bottom { border-top: 1px solid rgba(255,255,255,.12); padding-top: 1.5rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; font-size: .8125rem; color: rgba(255,255,255,.4); }
.footer-bottom-links { display: flex; gap: 1.25rem; flex-wrap: wrap; }
.footer-bottom-links a { color: rgba(255,255,255,.5); transition: color var(--transition); }
.footer-bottom-links a:hover { color: rgba(255,255,255,.8); }
.footer-bottom-links a:focus-visible { box-shadow: 0 0 0 3px rgba(255,255,255,.4); border-radius: 2px; }

/* ─── Social icons ──────────────────────────────────────────────────────── */
.social-links { display: flex; gap: .625rem; margin-top: 1rem; }
.social-link {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  color: rgba(255,255,255,.65);
  transition: border-color var(--transition), color var(--transition), background var(--transition);
}
.social-link:hover { border-color: rgba(255,255,255,.6); color: #fff; background: rgba(255,255,255,.1); }
.social-link:focus-visible { box-shadow: 0 0 0 3px rgba(255,255,255,.5); }

/* ─── Cart drawer overlay (status-region) ───────────────────────────────── */
.cart-status { position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 200; pointer-events: none; }

/* ─── Toast ─────────────────────────────────────────────────────────────── */
.toast-container { position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 300; display: flex; flex-direction: column; gap: .75rem; pointer-events: none; }
.toast {
  background: var(--clr-brand);
  color: #fff;
  padding: .875rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  box-shadow: 0 4px 16px rgba(0,0,0,.2);
  pointer-events: auto;
  display: flex; align-items: center; gap: .75rem;
  max-width: 320px;
}
.toast__icon { font-size: 1.1rem; flex-shrink: 0; }
@media (prefers-reduced-motion: no-preference) {
  .toast { animation: toast-in 250ms ease; }
  @keyframes toast-in {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: translateY(0); }
  }
}
.toast--exit { opacity: 0; transition: opacity 200ms ease; }

/* ─── Responsive ────────────────────────────────────────────────────────── */
@media (max-width: 960px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav { display: none; }
  .primary-nav.is-open { display: flex; position: fixed; inset: 0; top: 0; flex-direction: column; justify-content: flex-start; background: var(--clr-surface); z-index: 150; padding: 5rem 1.5rem 2rem; gap: 0; }
  .primary-nav.is-open .primary-nav__list { flex-direction: column; gap: .25rem; }
  .primary-nav.is-open .primary-nav__link { font-size: 1.25rem; padding: .875rem; }
  .menu-toggle { display: flex; align-items: center; justify-content: center; }

  .hero-inner { grid-template-columns: 1fr; min-height: auto; }
  .hero-image-wrap { display: none; }

  .deal-card { grid-template-columns: 100px 1fr; }

  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding-inline: 1rem; }
  .product-grid { grid-template-columns: 1fr 1fr; gap: .875rem; }
  .deals-grid { grid-template-columns: 1fr; }
  .product-card__footer { flex-direction: column; align-items: flex-start; gap: .5rem; }
}

/* ─── Forced colors ─────────────────────────────────────────────────────── */
@media (forced-colors: active) {
  .product-card, .deal-card, .editorial-card {
    border: 2px solid ButtonText;
  }
  .btn--primary { background: Highlight; color: HighlightText; border: 2px solid ButtonText; }
  .cart-badge { forced-color-adjust: none; }
  .product-card__badge { forced-color-adjust: none; }
}

