+/* ─── Design Tokens ─────────────────────────────────────────────────────── */
+:root {
+  --clr-brand:       #1a1a2e;
+  --clr-brand-mid:   #16213e;
+  --clr-accent:      #e94560;
+  --clr-accent-dark: #c73652;
