  'use strict';

  /* ── Announcement bar dismiss ─────────────────────────────────────────── */
  const announceBar = document.getElementById('announcement-bar');
  const dismissBtn  = document.getElementById('dismiss-announcement');
  if (announceBar && dismissBtn) {
    dismissBtn.addEventListener('click', () => {
      announceBar.hidden = true;
    });
  }

  /* ── Mobile nav toggle ────────────────────────────────────────────────── */
  const menuToggle  = document.getElementById('menu-toggle');
  const primaryNav  = document.getElementById('primary-nav');
  if (menuToggle && primaryNav) {
    menuToggle.addEventListener('click', () => {
      const isOpen = primaryNav.classList.toggle('is-open');
      menuToggle.setAttribute('aria-expanded', String(isOpen));
      menuToggle.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
      document.body.style.overflow = isOpen ? 'hidden' : '';

      // Move focus into nav when opened
      if (isOpen) {
        const firstLink = primaryNav.querySelector('a');
        if (firstLink) firstLink.focus();
      }
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && primaryNav.classList.contains('is-open')) {
        primaryNav.classList.remove('is-open');
        menuToggle.setAttribute('aria-expanded', 'false');
        menuToggle.setAttribute('aria-label', 'Open navigation menu');
        document.body.style.overflow = '';
        menuToggle.focus();
      }
    });
  }

  /* ── Toast notifications ──────────────────────────────────────────────── */
  const toastContainer = document.getElementById('toast-container');
  const liveRegion     = document.getElementById('cart-live-region');

  function showToast(message, icon = '✓') {
    if (!toastContainer) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.innerHTML = `<span class="toast__icon" aria-hidden="true">${icon}</span><span>${message}</span>`;
    toastContainer.appendChild(toast);

    // Announce to screen readers via live region
    if (liveRegion) liveRegion.textContent = message;

    setTimeout(() => {
      toast.classList.add('toast--exit');
      setTimeout(() => toast.remove(), 200);
    }, 3000);
  }

  /* ── Cart state ───────────────────────────────────────────────────────── */
  let cartCount = 0;
  const cartBadge = document.getElementById('cart-badge');
  const cartBtn   = document.getElementById('cart-btn');

  function updateCartBadge() {
    if (!cartBadge) return;
    cartBadge.textContent = cartCount;
    cartBadge.hidden = cartCount === 0;
    if (cartBtn) {
      cartBtn.setAttribute('aria-label', `Shopping cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`);
    }
  }

  function addToCart(productName) {
    cartCount++;
    updateCartBadge();
    showToast(`Added <strong>${productName}</strong> to cart`, '🛒');
  }

  /* ── Add-to-cart buttons ──────────────────────────────────────────────── */
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-add-to-cart]');
    if (btn) {
      const name = btn.dataset.addToCart;
      addToCart(name);
    }
  });

  /* ── Wishlist toggle ──────────────────────────────────────────────────── */
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-wishlist]');
    if (!btn) return;
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    const product = btn.dataset.wishlist;
    if (!pressed) {
      btn.textContent = '♥';
      showToast(`<strong>${product}</strong> saved to wishlist`, '♥');
    } else {
      btn.textContent = '♡';
    }
  });

  /* ── Countdown timer ──────────────────────────────────────────────────── */
  function updateCountdown() {
    const ends = document.querySelectorAll('[data-countdown-end]');
    ends.forEach(el => {
      const end = new Date(el.dataset.countdownEnd).getTime();
      const diff = Math.max(0, end - Date.now());
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      const fmt = (n) => String(n).padStart(2, '0');

      const hEl = el.querySelector('[data-cd-hours]');
      const mEl = el.querySelector('[data-cd-minutes]');
      const sEl = el.querySelector('[data-cd-seconds]');
      if (hEl) hEl.textContent = fmt(h);
      if (mEl) mEl.textContent = fmt(m);
      if (sEl) sEl.textContent = fmt(s);
    });
  }
  updateCountdown();
  setInterval(updateCountdown, 1000);

  /* ── Newsletter form ──────────────────────────────────────────────────── */
  const newsletterForm   = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');
  if (newsletterForm && newsletterStatus) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = newsletterForm.querySelector('input[type="email"]');
      if (!emailInput || !emailInput.value.trim()) {
        newsletterStatus.textContent = 'Please enter a valid email address.';
        newsletterStatus.className = 'newsletter-status newsletter-status--error';
        emailInput?.focus();
        return;
      }
      newsletterStatus.textContent = '🎉 You\'re subscribed! Check your inbox for a welcome offer.';
      newsletterStatus.className = 'newsletter-status newsletter-status--success';
      emailInput.value = '';
    });
  }

  /* ── Category filter ──────────────────────────────────────────────────── */
  const categoryPills = document.querySelectorAll('[data-category-filter]');
  categoryPills.forEach(pill => {
    pill.addEventListener('click', () => {
      categoryPills.forEach(p => p.removeAttribute('aria-current'));
      pill.setAttribute('aria-current', 'true');
    });
  });

  /* ── Init ─────────────────────────────────────────────────────────────── */
  updateCartBadge();
})();
